steps.code:
// class Coin: private int value, constructor,
//   toString returning e.g. "5 gold",
//   equals(Object other) comparing values

steps.solution:
class Coin {
  private int value;

  public Coin(int value) {
    this.value = value;
  }

  public String toString() {
    return value + " gold";
  }

  public boolean equals(Object other) {
    Coin c = (Coin) other;
    return value == c.value;
  }
}

