interface Openable {
  void open();
}

class Chest implements Openable {
  public void open() {
    System.out.println("The chest creaks open.");
  }
}

class Door implements Openable {
  public void open() {
    System.out.println("The door swings wide.");
  }
}

public void run() {
  useIt(new Chest());
  useIt(new Door());
}

