public void run() {
  new Slime("Blob").attack();
}

abstract class Monster {
  private String name;

  public Monster(String name) {
    this.name = name;
  }

  public String getName() {
    return name;
  }

  public abstract void attack();
}

class Slime extends Monster {
  public Slime(String name) {
    super(name);
  }

  public void attack() {
    System.out.println(getName() + " splatters you.");
  }
}

