steps.solution:
interface Lightable {
  void light();
}

class Torch implements Lightable {
  public void light() {
    System.out.println("The torch catches fire.");
  }
}

class Spell implements Lightable {
  public void light() {
    System.out.println("The spell glows.");
  }
}
